package com.healthwise.report.entity;import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;
/** PDF-free laboratory report metadata. */@Document("reports")public class Report{@Id private String id;@Indexed private String userId;@Indexed private String recommendationId;private String reportName;private Instant uploadedAt;private String reportType;public String getId(){return id;}public String getUserId(){return userId;}public String getRecommendationId(){return recommendationId;}public String getReportName(){return reportName;}public Instant getUploadedAt(){return uploadedAt;}public String getReportType(){return reportType;}public void setUserId(String v){userId=v;}public void setRecommendationId(String v){recommendationId=v;}public void setReportName(String v){reportName=v;}public void setUploadedAt(Instant v){uploadedAt=v;}public void setReportType(String v){reportType=v;}}
